// Pick ONE due row: status=ready AND scheduledAt<=now(Asia/Bangkok). Sort asc, take first.
// ALWAYS emit exactly one item carrying hasDue flag so the lock-release path is reachable on empty.
const rows = $input.all().map(i => i.json);
const nowBkk = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Bangkok' }));
const due = rows
  .filter(r => String(r.status || '').trim() === 'ready')
  .filter(r => {
    const s = r.scheduledAt;
    if (!s) return false;
    const d = new Date(s);
    return !isNaN(d) && d <= nowBkk;
  })
  .sort((a, b) => new Date(a.scheduledAt) - new Date(b.scheduledAt));
if (due.length === 0) return [{ json: { hasDue: false } }];
const row = due[0];
if (row.row_number === undefined || row.row_number === null) throw new Error('mkt_scheduler: read node must expose row_number for write-back');
return [{ json: { hasDue: true, ...row } }];

// Build asset spec + platform list from the claimed row.
const row = $('Pick one due row').first().json;
const platforms = String(row.platforms || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
if (platforms.length === 0) throw new Error('mkt_scheduler: row has no platforms');
const driveFolderId = String(row.driveFolderId || '').trim();
// heroFile = exact image filename within the (possibly shared) Drive folder. Blank -> legacy hero.png fallback.
const heroFile = String(row.heroFile || '').trim() || 'hero.png';
// assetType routes the publish path: image (default/legacy) | carousel | video.
// heroFile is REUSED for all 3: 1 filename (image/video) or comma-separated list (carousel).
const assetType = (String(row.assetType || '').trim().toLowerCase()) || 'image';
return [{ json: {
  id: row.id,
  rowNumber: row.row_number,
  product: row.product,
  copyVi: row.copyVi || '',
  copyEn: row.copyEn || '',
  copyThreads: row.copyThreads || '',
  copyX: row.copyX || '',
  platforms,
  driveFolderId,
  heroFile,
  assetType
} }];

// Resolve the post's hero image by filename (spec.heroFile) within the Drive folder.
// Shared-folder model: one campaign/project folder holds many images; the row names which one.
// Drive does NOT enforce unique filenames -> guard against >1 match (loud error beats wrong image).
const spec = $('Build post spec').first().json;
const files = $input.all().map(i => i.json).filter(f => f && f.id);
const want = String(spec.heroFile || 'hero.png').toLowerCase();
const matches = files.filter(f => (f.name || '').toLowerCase() === want);
if (matches.length === 0) {
  return [{ json: { __invalid: true, id: spec.id, rowNumber: spec.rowNumber, error: `heroFile '${spec.heroFile}' not found in Drive folder ${spec.driveFolderId}` } }];
}
if (matches.length > 1) {
  return [{ json: { __invalid: true, id: spec.id, rowNumber: spec.rowNumber, error: `ambiguous heroFile '${spec.heroFile}': ${matches.length} files share this name in folder ${spec.driveFolderId}` } }];
}
return [{ json: { ...spec, heroFileId: matches[0].id } }];

// Normalize FB /photos response (or error) into contract {results:[{platform,ok,url,error}]}.
// Both success + continueErrorOutput branches land here; $json carries whichever fired.
const meta = $('Validate assets').first().json;
const platforms = meta.platforms || [];
const resp = $json || {};
const results = [];
if (platforms.includes('facebook')) {
  const errObj = resp.error;
  const pid = resp.post_id || resp.id;
  if (pid && !errObj) {
    results.push({ platform:'facebook', ok:true, url:`https://facebook.com/${pid}`, error:null });
  } else {
    let msg = 'FB publish failed';
    if (errObj) msg = typeof errObj==='string' ? errObj : (errObj.message || JSON.stringify(errObj));
    else if (resp.message) msg = resp.message;
    results.push({ platform:'facebook', ok:false, url:null, error:('FB: '+msg).slice(0,300) });
  }
}
// (Threads + other platforms handled by their own dedicated branches downstream.)
return [{ json: { id: meta.id, rowNumber: meta.rowNumber, results } }];

// Aggregate per-platform results → terminal status + write-back payload.
const row = $json;
const results = row.results || [];
const okCount = results.filter(r => r.ok).length;
let status;
if (okCount === results.length && okCount > 0) status = 'posted';
else if (okCount > 0) status = 'partial';
else status = 'error';
const postUrl = {};
for (const r of results) if (r.ok && r.url) postUrl[r.platform] = r.url;
const errParts = results.filter(r => !r.ok).map(r => `${r.platform}:${r.error}`);
return [{ json: {
  id: row.id,
  row_number: row.rowNumber,
  status,
  postUrl: JSON.stringify(postUrl),
  postedAt: new Date().toISOString(),
  error: errParts.join(' | ').slice(0, 500)
} }];

// Validation-error path: build write-back marking row=error, no network post happened.
const v = $json;
return [{ json: {
  id: v.id,
  row_number: v.rowNumber,
  status: 'error',
  postUrl: '{}',
  postedAt: new Date().toISOString(),
  error: (v.error || 'validation failed').slice(0, 500)
} }];

// Threads adapter step 1: gate + build creation-container request. Carry FB results forward.
// FB branch may have been skipped (platforms has no 'facebook') -> Normalize FB result didn't run.
const spec = $('Validate assets').first().json;
let fbResults = [];
let id = spec.id, rowNumber = spec.rowNumber;
try {
  const fb = $('Normalize FB result').first().json;
  if (fb && Array.isArray(fb.results)) { fbResults = fb.results; id = fb.id; rowNumber = fb.rowNumber; }
} catch (e) { /* FB branch skipped; keep empty fbResults */ }
const platforms = spec.platforms || [];
const carry = { id, rowNumber, fbResults };
if (!platforms.includes('threads')) { return [{ json: { ...carry, skipThreads: true } }]; }
const imageUrl = `https://lh3.googleusercontent.com/d/${spec.heroFileId}`;
let text = String(spec.copyThreads || '').trim();
if (!text) { text = String(spec.copyVi || ''); if (text.length > 500) { text = text.slice(0, 497); text = text.slice(0, text.lastIndexOf(' ')) + '…'; } }
return [{ json: { ...carry, skipThreads: false, imageUrl, text } }];

// Threads final: confirm publish, attach REAL permalink, append to fbResults -> single results[].
const carry = $('Build Threads request').first().json;
const results = [...(carry.fbResults || [])];
if (!carry.skipThreads) {
  const pubItem = $('Threads publish').first();
  const pub = (pubItem && pubItem.json) || {};
  const perma = $json || {};
  const mediaId = pub.id;
  const pubErr = pub.error;
  if (mediaId && !pubErr) {
    // permalink GET may have failed (onError) -> fall back to media-id reference
    const url = perma.permalink || `https://www.threads.net/@me/post/${mediaId}`;
    results.push({ platform: 'threads', ok: true, url, error: null });
  } else {
    let msg = 'Threads publish failed';
    if (pubErr) msg = typeof pubErr === 'string' ? pubErr : (pubErr.message || JSON.stringify(pubErr));
    results.push({ platform: 'threads', ok: false, url: null, error: ('Threads: ' + msg).slice(0, 300) });
  }
}
return [{ json: { id: carry.id, rowNumber: carry.rowNumber, results } }];

// IG adapter step 1: gate + build media-container inputs. Carry Threads/FB results forward.
// 'Normalize Threads result' ALWAYS runs (both IF-threads branches converge) -> emits {id,rowNumber,results}.
const prev = $('Normalize Threads result').first().json;
const spec = $('Validate assets').first().json;
const results = [...(prev.results || [])];
const carry = { id: prev.id, rowNumber: prev.rowNumber, priorResults: results };
const platforms = spec.platforms || [];
if (!platforms.includes('instagram')) { return [{ json: { ...carry, skipIg: true } }]; }
// IG = URL-fetch model (like Threads): public Drive link, platform server fetches it.
const imageUrl = `https://lh3.googleusercontent.com/d/${spec.heroFileId}`;
// IG audience -> English copy. Caption limit 2200 (generous); truncate defensively.
let caption = String(spec.copyEn || spec.copyVi || '');
if (caption.length > 2200) { caption = caption.slice(0, 2197); caption = caption.slice(0, caption.lastIndexOf(' ')) + '…'; }
return [{ json: { ...carry, skipIg: false, imageUrl, caption } }];

// IG final: confirm publish, attach REAL permalink, append to priorResults -> single results[].
const carry = $('Build IG request').first().json;
const results = [...(carry.priorResults || [])];
if (!carry.skipIg) {
  const pubItem = $('IG publish').first();
  const pub = (pubItem && pubItem.json) || {};
  const perma = $json || {};
  const mediaId = pub.id;
  const pubErr = pub.error;
  if (mediaId && !pubErr) {
    const url = perma.permalink || `https://www.instagram.com/p/${mediaId}`;
    results.push({ platform: 'instagram', ok: true, url, error: null });
  } else {
    let msg = 'Instagram publish failed';
    if (pubErr) msg = typeof pubErr === 'string' ? pubErr : (pubErr.message || JSON.stringify(pubErr));
    results.push({ platform: 'instagram', ok: false, url: null, error: ('Instagram: ' + msg).slice(0, 300) });
  }
}
return [{ json: { id: carry.id, rowNumber: carry.rowNumber, results } }];

// LinkedIn adapter step 1: gate + carry prior results forward.
// 'Normalize IG result' ALWAYS runs (both IG IF branches converge) -> {id,rowNumber,results}.
const prev = $('Normalize IG result').first().json;
const spec = $('Validate assets').first().json;
const results = [...(prev.results || [])];
const carry = { id: prev.id, rowNumber: prev.rowNumber, priorResults: results, heroFileId: spec.heroFileId };
const platforms = spec.platforms || [];
if (!platforms.includes('linkedin')) { return [{ json: { ...carry, skipLi: true } }]; }
// LinkedIn commentary limit 3000 chars (generous); long-form like FB -> copyVi.
let commentary = String(spec.copyVi || spec.copyEn || '');
if (commentary.length > 3000) { commentary = commentary.slice(0, 2997); commentary = commentary.slice(0, commentary.lastIndexOf(' ')) + '…'; }
const owner = 'urn:li:person:' + String($env.MKT_LINKEDIN_PERSON_ID || '');
return [{ json: { ...carry, skipLi: false, commentary, owner } }];

// LinkedIn final: read post URN from x-restli-id header, append to priorResults.
const carry = $('Build LinkedIn request').first().json;
const results = [...(carry.priorResults || [])];
if (!carry.skipLi) {
  const item = $('LI create post').first();
  const resp = (item && item.json) || {};
  const headers = resp.headers || {};
  const code = resp.statusCode || resp.status;
  const urn = headers['x-restli-id'] || headers['X-RestLi-Id'];
  const body = resp.body || resp;
  if (urn && (!code || code === 201 || code === 200)) {
    results.push({ platform: 'linkedin', ok: true, url: 'https://www.linkedin.com/feed/update/' + urn, error: null });
  } else {
    let msg = 'LinkedIn publish failed';
    if (body && body.message) msg = body.message;
    else if (body && body.error) msg = typeof body.error === 'string' ? body.error : JSON.stringify(body.error);
    results.push({ platform: 'linkedin', ok: false, url: null, error: ('LinkedIn: ' + msg).slice(0, 300) });
  }
}
return [{ json: { id: carry.id, rowNumber: carry.rowNumber, results } }];

// X adapter step 1: gate + carry forward. NOTE: not live-tested (no API credit).
const prev = $('Normalize LinkedIn result').first().json;
const spec = $('Validate assets').first().json;
const results = [...(prev.results || [])];
const carry = { id: prev.id, rowNumber: prev.rowNumber, priorResults: results, heroFileId: spec.heroFileId };
const platforms = spec.platforms || [];
if (!platforms.includes('x') && !platforms.includes('twitter')) { return [{ json: { ...carry, skipX: true } }]; }
// X hard limit 280 chars -> prefer short variant (copyThreads), else truncate copyVi.
let text = String(spec.copyX || '').trim();
if (!text) text = String(spec.copyThreads || '').trim();
if (!text) text = String(spec.copyVi || '');
if (text.length > 280) { text = text.slice(0, 277); text = text.slice(0, text.lastIndexOf(' ')) + '…'; }
return [{ json: { ...carry, skipX: false, text } }];

// X final: append result. Guard upstream nodes that may be skipped on upload/publish failure.
const carry = $('Build X request').first().json;
const results = [...(carry.priorResults || [])];
if (!carry.skipX) {
  // upload error surfaces on the X upload media node (continueErrorOutput)
  let uploadErr = null;
  try { const u = $('X upload media').first(); uploadErr = (u && u.json && u.json.error) || null; } catch (e) {}
  let tid = null, pubErr = null;
  try {
    const item = $('X create tweet').first();
    const resp = (item && item.json) || {};
    tid = (resp.data && resp.data.id) || null;
    pubErr = resp.errors || resp.error || resp.title || null;
  } catch (e) { /* create tweet skipped because upload failed */ }
  if (tid && !pubErr) {
    results.push({ platform: 'x', ok: true, url: 'https://twitter.com/i/web/status/' + tid, error: null });
  } else {
    let msg = 'X publish failed';
    const e = pubErr || uploadErr;
    if (e) msg = typeof e === 'string' ? e : (e.message || JSON.stringify(e));
    else if (!tid) msg = 'X media upload failed (no media id)';
    results.push({ platform: 'x', ok: false, url: null, error: ('X: ' + msg).slice(0, 300) });
  }
}
return [{ json: { id: carry.id, rowNumber: carry.rowNumber, results } }];

// Sub-workflow threw (missing file / FB error): build an error result so the
// orchestrator still aggregates + writes back (row=error) + releases the lock.
// id/rowNumber come from Build post spec (always present), not the error payload.
const spec = $('Build post spec').first().json;
const e = $json && ($json.error || $json.message || $json);
let msg = 'carousel publish failed';
if (e) msg = typeof e === 'string' ? e : (e.message || JSON.stringify(e));
return [{ json: { id: spec.id, rowNumber: spec.rowNumber, results: [{ platform: 'facebook', ok: false, url: null, error: ('carousel: ' + msg).slice(0, 300) }] } }];

// Video sub-workflow threw (missing file / FB error): build an error result so
// the orchestrator still aggregates + writes back (row=error) + releases the lock.
const spec = $('Build post spec').first().json;
const e = $json && ($json.error || $json.message || $json);
let msg = 'video publish failed';
if (e) msg = typeof e === 'string' ? e : (e.message || JSON.stringify(e));
return [{ json: { id: spec.id, rowNumber: spec.rowNumber, results: [{ platform: 'facebook', ok: false, url: null, error: ('video: ' + msg).slice(0, 300) }] } }];
